// Profile page
// Shows the logged-in user's name and email
// Also lets the user update their password, send monthly report email, and logout

import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import Navbar from '../components/Navbar';
import './Profile.css';

function Profile() {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [profileError, setProfileError] = useState('');

  // Email report state
  const [reportMonth, setReportMonth] = useState('');
  const [emailMessage, setEmailMessage] = useState('');
  const [emailError, setEmailError] = useState('');
  const [emailLoading, setEmailLoading] = useState(false);

  const token = localStorage.getItem('token');
  const navigate = useNavigate();

  useEffect(() => {
    fetchProfile();
    // Set default month to current month
    const today = new Date();
    setReportMonth(today.toISOString().substring(0, 7));
  }, []);

  const fetchProfile = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/auth/profile', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setName(response.data.name);
      setEmail(response.data.email);
    } catch (err) {
      console.log('Profile fetch error:', err.response?.data || err.message);
      setProfileError(err.response?.data?.message || 'Could not load profile');
    }
  };

  // Handle password update
  const handleUpdatePassword = async (e) => {
    e.preventDefault();
    setMessage('');
    setError('');

    try {
      const response = await axios.put(
        'http://localhost:5000/api/auth/update-password',
        { currentPassword, newPassword },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      setMessage(response.data.message);
      setCurrentPassword('');
      setNewPassword('');

    } catch (err) {
      setError(err.response?.data?.message || 'Failed to update password');
    }
  };

  // Send monthly report email
  const handleSendReport = async (e) => {
    e.preventDefault();
    setEmailMessage('');
    setEmailError('');
    setEmailLoading(true);

    try {
      const response = await axios.post(
        'http://localhost:5000/api/email/monthly-report',
        { month: reportMonth },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setEmailMessage(response.data.message);
    } catch (err) {
      setEmailError(err.response?.data?.message || 'Failed to send email');
    }

    setEmailLoading(false);
  };

  // Logout
  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    navigate('/login');
  };

  return (
    <div>
      <Navbar />
      <div className="profile-container">

        <h2 className="profile-heading">My Profile</h2>

        {/* User Info Section */}
        <div className="profile-card">
          <h3>Account Details</h3>
          {profileError ? (
            <p className="error-msg">{profileError}</p>
          ) : (
            <>
              <div className="profile-field">
                <label>Name</label>
                <p>{name}</p>
              </div>
              <div className="profile-field">
                <label>Email</label>
                <p>{email}</p>
              </div>
            </>
          )}
        </div>

        {/* Update Password Section */}
        <div className="profile-card">
          <h3>Update Password</h3>
          <form onSubmit={handleUpdatePassword}>
            <input
              type="password"
              placeholder="Current Password"
              value={currentPassword}
              onChange={(e) => setCurrentPassword(e.target.value)}
              required
            />
            <input
              type="password"
              placeholder="New Password"
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              required
            />
            <button type="submit" className="update-btn">
              Update Password
            </button>
          </form>

          {message && <p className="success-msg">{message}</p>}
          {error && <p className="error-msg">{error}</p>}
        </div>

        {/* Monthly Report Email Section */}
        <div className="profile-card">
          <h3>📧 Send Monthly Report</h3>
          <p className="card-subtext">
            Get a detailed transaction report sent to your email.
            Make sure EMAIL_USER and EMAIL_PASS are set in backend .env
          </p>
          <form onSubmit={handleSendReport} className="email-form">
            <input
              type="month"
              value={reportMonth}
              onChange={(e) => setReportMonth(e.target.value)}
              required
            />
            <button type="submit" className="send-email-btn" disabled={emailLoading}>
              {emailLoading ? 'Sending...' : '📤 Send Report'}
            </button>
          </form>
          {emailMessage && <p className="success-msg">{emailMessage}</p>}
          {emailError && <p className="error-msg">{emailError}</p>}
        </div>

        {/* Logout Button */}
        <div className="profile-card">
          <h3>Session</h3>
          <button className="logout-btn" onClick={handleLogout}>
            Logout
          </button>
        </div>

      </div>
    </div>
  );
}

export default Profile;
